import collections,hashlib,json,re,subprocess,sys,xml.etree.ElementTree as ET
from pathlib import Path
work=Path(sys.argv[1]);expected=json.loads((work/'expected-private.json').read_text());out=work/'assessment-exact-margins.json';assert not out.exists();results={}
squash=lambda v:re.sub(r'\s+','',str(v))
for case in ('course','batch','batch_stress'):
 pdf=work/(case+'.pdf');subprocess.run(['pdftotext','-raw',str(pdf),str(work/(case+'-raw-private.txt'))],check=True);subprocess.run(['pdftotext','-bbox',str(pdf),str(work/(case+'-bbox-private.html'))],check=True)
 text=squash((work/(case+'-raw-private.txt')).read_text());report=expected[case];cells=collections.Counter(squash(v) for row in report['rows'] for v in row if v not in (None,''));missing=[{'expected_occurrences':count,'found_occurrences':text.count(value),'cell_sha256':hashlib.sha256(value.encode()).hexdigest()} for value,count in cells.items() if text.count(value)<count]
 headers=[{'header':name,'present':squash(name) in text} for name in report['headers']];funnel=[{'value':value,'present':squash(value) in text} for value in report['funnel']]
 xml=ET.parse(work/(case+'-bbox-private.html'));pages=xml.findall('.//{*}page');words=xml.findall('.//{*}word');right=max(float(w.attrib['xMax']) for w in words);left=min(float(w.attrib['xMin']) for w in words);a4=all(abs(float(p.attrib['width'])-595)<1 and abs(float(p.attrib['height'])-842)<1 for p in pages)
 result={'rows':len(report['rows']),'columns':len(report['headers']),'pages':len(pages),'A4':a4,'headers':headers,'missing_cell_counts':missing,'funnel':funnel,'leftmost_word_pt':left,'rightmost_word_pt':right,'all_text_within_A4_15mm_margins':left>=15*72/25.4-0.5 and right<=595-15*72/25.4+0.5,'pdf_sha256':hashlib.sha256(pdf.read_bytes()).hexdigest()};result['pass']=a4 and not missing and all(h['present'] for h in headers) and all(f['present'] for f in funnel) and result['all_text_within_A4_15mm_margins'];results[case]=result
proof={'exit_code':0 if all(v['pass'] for v in results.values()) else 1,'cases':results,'harness_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()};out.write_text(json.dumps(proof,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'exit_code':proof['exit_code'],'cases':{k:{'pass':v['pass'],'rows':v['rows'],'columns':v['columns'],'missing_cells':len(v['missing_cell_counts']),'missing_headers':[h['header'] for h in v['headers'] if not h['present']],'rightmost_word_pt':v['rightmost_word_pt']} for k,v in results.items()}},ensure_ascii=False));raise SystemExit(proof['exit_code'])
